import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int big = sc.nextInt();
        int small = sc.nextInt();
        System.out.println("本喵{w}的版本：" + big + "." + small);
        System.out.println("中间那个点，把两个数串成一条喵");
    }
}
